"""Adapter for the partner settlement API."""

from decimal import Decimal


def _to_fractional_units(amount_cents: int) -> Decimal:
    # engineering-decision: partner-settlement-fractional-amounts | docs/engineering/decisions/partner-settlement-fractional-amounts.md
    # Decimal division avoids binary float rounding error on money.
    return Decimal(amount_cents) / 100


def to_partner_payload(order: dict) -> dict:
    return {
        "orderId": order["id"],
        "partner": order["partner_id"],
        "amount": _to_fractional_units(order["amount_cents"]),
    }

